--
-- Name: absences; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.absences (
    absence_id integer NOT NULL,
    employee_id integer NOT NULL,
    absence_date date NOT NULL,
    weekday smallint GENERATED ALWAYS AS ((EXTRACT(isodow FROM absence_date))::smallint) STORED,
    absence_type text NOT NULL,
    reason text NOT NULL,
    is_justified boolean NOT NULL,
    CONSTRAINT absences_absence_date_check CHECK (((EXTRACT(isodow FROM absence_date) >= (1)::numeric) AND (EXTRACT(isodow FROM absence_date) <= (5)::numeric))),
    CONSTRAINT absences_absence_type_check CHECK ((absence_type = ANY (ARRAY['Planned leave'::text, 'Unplanned'::text])))
);


--
-- Name: departments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.departments (
    dept_id smallint NOT NULL,
    dept_name text NOT NULL
);


--
-- Name: employees; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.employees (
    employee_id integer NOT NULL,
    dept_id smallint NOT NULL,
    manager_id integer,
    job_role text NOT NULL,
    gender text NOT NULL,
    age smallint NOT NULL,
    overtime_flag boolean NOT NULL,
    job_satisfaction smallint NOT NULL,
    work_life_balance smallint NOT NULL,
    distance_from_home smallint NOT NULL,
    years_at_company smallint NOT NULL,
    hire_date date NOT NULL,
    CONSTRAINT employees_age_check CHECK (((age >= 18) AND (age <= 70))),
    CONSTRAINT employees_check CHECK ((manager_id IS DISTINCT FROM employee_id)),
    CONSTRAINT employees_distance_from_home_check CHECK ((distance_from_home >= 0)),
    CONSTRAINT employees_gender_check CHECK ((gender = ANY (ARRAY['Male'::text, 'Female'::text]))),
    CONSTRAINT employees_job_satisfaction_check CHECK (((job_satisfaction >= 1) AND (job_satisfaction <= 4))),
    CONSTRAINT employees_work_life_balance_check CHECK (((work_life_balance >= 1) AND (work_life_balance <= 4))),
    CONSTRAINT employees_years_at_company_check CHECK ((years_at_company >= 0))
);


