CREATE TABLE public.weekly_workload (
    workload_id integer NOT NULL,
    employee_id integer NOT NULL,
    week_start date NOT NULL,
    hours_worked numeric(4,1) NOT NULL,
    overtime_hours numeric(4,1) GENERATED ALWAYS AS (GREATEST((hours_worked - (40)::numeric), (0)::numeric)) STORED,
    CONSTRAINT weekly_workload_hours_worked_check CHECK (((hours_worked >= (0)::numeric) AND (hours_worked <= (90)::numeric))),
    CONSTRAINT weekly_workload_week_start_check CHECK ((EXTRACT(isodow FROM week_start) = (1)::numeric))
);


--
-- Name: v_kpi1_overtime_by_dept_month; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_kpi1_overtime_by_dept_month AS
 SELECT d.dept_name,
    (date_trunc('month'::text, (w.week_start)::timestamp with time zone))::date AS month,
    count(DISTINCT w.employee_id) AS employees,
    round(avg(w.overtime_hours), 2) AS avg_weekly_overtime_h,
    round((sum(w.overtime_hours) / (count(DISTINCT w.employee_id))::numeric), 2) AS overtime_h_per_employee_month
   FROM ((public.weekly_workload w
     JOIN public.employees e USING (employee_id))
     JOIN public.departments d USING (dept_id))
  GROUP BY d.dept_name, (date_trunc('month'::text, (w.week_start)::timestamp with time zone));


--
-- Name: v_kpi2_alerts_by_dept; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_kpi2_alerts_by_dept AS
 SELECT d.dept_name,
    count(a.employee_id) AS alerts,
    count(*) AS headcount,
    round(((100.0 * (count(a.employee_id))::numeric) / (count(*))::numeric), 2) AS alert_rate_pct
   FROM ((public.employees e
     JOIN public.departments d ON ((d.dept_id = e.dept_id)))
     LEFT JOIN public.fn_burnout_alerts() a(employee_id, dept_name, manager_id, avg_hours_recent, min_hours_recent, leave_days_in_window) ON ((a.employee_id = e.employee_id)))
  GROUP BY d.dept_name;


--
-- Name: v_kpi2_streak_history; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_kpi2_streak_history AS
 WITH hot AS (
         SELECT weekly_workload.employee_id,
            weekly_workload.week_start
           FROM public.weekly_workload
          WHERE (weekly_workload.hours_worked > (50)::numeric)
        ), grp AS (
         SELECT hot.employee_id,
            hot.week_start,
            (hot.week_start - ((row_number() OVER (PARTITION BY hot.employee_id ORDER BY hot.week_start))::integer * 7)) AS island
           FROM hot
        )
 SELECT employee_id,
    min(week_start) AS streak_start,
    max(week_start) AS streak_end,
    count(*) AS weeks
   FROM grp
  GROUP BY employee_id, island
 HAVING (count(*) >= 4);


