CREATE VIEW public.v_reporting_period AS
 SELECT min(week_start) AS period_start,
    (max(week_start) + 6) AS period_end
   FROM public.weekly_workload;


--
-- Name: v_kpi3_unplanned_rate_by_manager_weekday; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_kpi3_unplanned_rate_by_manager_weekday AS
 WITH per AS (
         SELECT v_reporting_period.period_start,
            v_reporting_period.period_end
           FROM public.v_reporting_period
        ), cal AS (
         SELECT (EXTRACT(isodow FROM g.g))::integer AS weekday,
            count(*) AS work_days
           FROM per,
            LATERAL generate_series((per.period_start)::timestamp without time zone, (per.period_end)::timestamp without time zone, '1 day'::interval) g(g)
          WHERE ((EXTRACT(isodow FROM g.g) >= (1)::numeric) AND (EXTRACT(isodow FROM g.g) <= (5)::numeric))
          GROUP BY ((EXTRACT(isodow FROM g.g))::integer)
        ), team AS (
         SELECT employees.manager_id,
            count(*) AS team_size
           FROM public.employees
          WHERE (employees.manager_id IS NOT NULL)
          GROUP BY employees.manager_id
        ), den AS (
         SELECT t.manager_id,
            c.weekday,
            t.team_size,
            (t.team_size * c.work_days) AS total_work_days
           FROM (team t
             CROSS JOIN cal c)
        ), num AS (
         SELECT e.manager_id,
            a.weekday,
            count(*) FILTER (WHERE (a.absence_type = 'Unplanned'::text)) AS unplanned_days,
            count(*) FILTER (WHERE ((a.absence_type = 'Unplanned'::text) AND (NOT a.is_justified))) AS unjustified_days
           FROM (public.absences a
             JOIN public.employees e USING (employee_id))
          WHERE (e.manager_id IS NOT NULL)
          GROUP BY e.manager_id, a.weekday
        )
 SELECT den.manager_id,
    den.weekday,
    (ARRAY['Mon'::text, 'Tue'::text, 'Wed'::text, 'Thu'::text, 'Fri'::text])[den.weekday] AS weekday_name,
    den.team_size,
    den.total_work_days,
    COALESCE(num.unplanned_days, (0)::bigint) AS unplanned_days,
    COALESCE(num.unjustified_days, (0)::bigint) AS unjustified_days,
    round(((100.0 * (COALESCE(num.unplanned_days, (0)::bigint))::numeric) / (den.total_work_days)::numeric), 2) AS unplanned_rate_pct,
    round(((100.0 * (COALESCE(num.unjustified_days, (0)::bigint))::numeric) / (den.total_work_days)::numeric), 2) AS unjustified_rate_pct
   FROM (den
     LEFT JOIN num USING (manager_id, weekday));


--
-- Name: v_kpi3_by_manager; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_kpi3_by_manager AS
 SELECT manager_id,
    max(team_size) AS team_size,
    sum(unplanned_days) AS unplanned_days,
    round(((100.0 * sum(unplanned_days)) / sum(total_work_days)), 2) AS unplanned_rate_pct,
    rank() OVER (ORDER BY (sum(unplanned_days) / sum(total_work_days)) DESC) AS rank_worst_first
   FROM public.v_kpi3_unplanned_rate_by_manager_weekday
  GROUP BY manager_id;


--
-- Name: v_kpi3_by_weekday; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_kpi3_by_weekday AS
 SELECT weekday,
    weekday_name,
    sum(total_work_days) AS total_work_days,
    sum(unplanned_days) AS unplanned_days,
    sum(unjustified_days) AS unjustified_days,
    round(((100.0 * sum(unplanned_days)) / sum(total_work_days)), 2) AS unplanned_rate_pct,
    round(((100.0 * sum(unjustified_days)) / sum(total_work_days)), 2) AS unjustified_rate_pct
   FROM public.v_kpi3_unplanned_rate_by_manager_weekday
  GROUP BY weekday, weekday_name;


--
-- Name: v_kpi3_reason_by_weekday; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_kpi3_reason_by_weekday AS
 SELECT weekday,
    reason,
    count(*) AS absence_days,
    round(((100.0 * (count(*))::numeric) / sum(count(*)) OVER (PARTITION BY weekday)), 1) AS share_of_weekday_pct
   FROM public.absences
  WHERE (absence_type = 'Unplanned'::text)
  GROUP BY weekday, reason;


